/**
 * Checks whether a specific permission has been authorized for this app by the current user.
 *
 * @param permission - The permission identifier to check.
 * @returns A promise resolving to `true` if the permission is authorized, `false` otherwise.
 * @public
 */
export type IsPermissionAuthorized = (permission: string) => Promise<boolean>;
/** @public */
export declare const isPermissionAuthorized: IsPermissionAuthorized;
